{
  "title": "Tính khoảng cách từ I đến mặt phẳng (ABC) trong tứ diện ABCD",
  "memory_declarations": [
    {
      "name": "ABC",
      "type": "plane3",
      "model_assumption": "Mặt phẳng (ABC) được định nghĩa bởi ba điểm A, B, C"
    },
    {
      "name": "distance_i_abc",
      "type": "float",
      "model_assumption": "Khoảng cách từ điểm I đến mặt phẳng (ABC)"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc tọa độ vì AB, AC, AD đôi một vuông góc",
      "source_fact_id": "ab_ac_ad_vuong_goc"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [4, 0, 0],
      "model_assumption": "Đặt B trên trục x, cách A 4 đơn vị",
      "source_fact_id": "ab_length"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 4, 0],
      "model_assumption": "Đặt C trên trục y, cách A 4 đơn vị",
      "source_fact_id": "ac_length"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 0, 4],
      "model_assumption": "Đặt D trên trục z, cách A 4 đơn vị",
      "source_fact_id": "ad_length"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "B",
        "b": "C"
      },
      "label": "Trung điểm M của BC",
      "source_fact_id": "m_midpoint_bc"
    },
    {
      "kind": "construct_point",
      "target_var": "N",
      "expr": {
        "kind": "midpoint",
        "a": "B",
        "b": "D"
      },
      "label": "Trung điểm N của BD",
      "source_fact_id": "n_midpoint_bd"
    },
    {
      "kind": "construct_line",
      "target_var": "CN_line",
      "through_a": "C",
      "through_b": "N",
      "label": "Đường thẳng CN"
    },
    {
      "kind": "construct_line",
      "target_var": "DM_line",
      "through_a": "D",
      "through_b": "M",
      "label": "Đường thẳng DM"
    },
    {
      "kind": "construct_point",
      "target_var": "I",
      "expr": {
        "kind": "intersect_line_line",
        "line_a": "CN_line",
        "line_b": "DM_line"
      },
      "label": "Giao điểm I của CN và DM",
      "source_fact_id": "i_intersection_cn_dm"
    },
    {
      "kind": "construct_plane",
      "target_var": "ABC",
      "through": ["A", "B", "C"],
      "label": "Mặt phẳng (ABC)"
    },
    {
      "kind": "assign",
      "target_var": "distance_i_abc",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "I",
        "wrt": "ABC"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách sử dụng tọa độ để giải quyết các bài toán hình học không gian, đặc biệt là việc tính khoảng cách từ một điểm đến một mặt phẳng."
}

{
  "title": "Khoảng cách từ hình chiếu đến mặt phẳng đáy trong lăng trụ đứng",
  "memory_declarations": [
    {
      "name": "(ABC)",
      "type": "plane3",
      "model_assumption": "Mặt phẳng đáy của lăng trụ"
    },
    {
      "name": "dist_h_abc",
      "type": "float",
      "model_assumption": "Khoảng cách từ H đến mặt phẳng đáy (ABC)"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc tọa độ"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [3, 0, 0],
      "source_fact_id": "ab_length",
      "model_assumption": "Đặt AB dọc theo trục x"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 4, 0],
      "source_fact_id": "ac_length",
      "model_assumption": "Đặt AC dọc theo trục y, vuông góc với AB"
    },
    {
      "kind": "declare_point",
      "target_var": "A_prime",
      "at": [0, 0, 4],
      "source_fact_id": "aa_prime_length",
      "model_assumption": "Đặt AA' dọc theo trục z vì lăng trụ đứng"
    },
    {
      "kind": "declare_point",
      "target_var": "B_prime",
      "at": [3, 0, 4],
      "model_assumption": "Xác định B' từ B và AA' theo tính chất lăng trụ đứng"
    },
    {
      "kind": "declare_point",
      "target_var": "C_prime",
      "at": [0, 4, 4],
      "model_assumption": "Xác định C' từ C và AA' theo tính chất lăng trụ đứng"
    },
    {
      "kind": "construct_plane",
      "target_var": "(ABC)",
      "through": ["A", "B", "C"],
      "label": "Mặt phẳng đáy (ABC)"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_A_prime_BC",
      "through": ["A_prime", "B", "C"],
      "label": "Mặt phẳng (A'BC)"
    },
    {
      "kind": "construct_point",
      "target_var": "H",
      "expr": {
        "kind": "project_onto",
        "point": "A",
        "target": "plane_A_prime_BC"
      },
      "source_fact_id": "h_hinh_chieu",
      "label": "Hình chiếu H của A lên (A'BC)"
    },
    {
      "kind": "assign",
      "target_var": "dist_h_abc",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "H",
        "wrt": "(ABC)"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách xác định hình chiếu vuông góc của một điểm lên một mặt phẳng và tính khoảng cách từ điểm đó đến một mặt phẳng khác trong không gian."
}

{
