      "source_fact_id": "canh_hinh_lap_phuong"
    },
    {
      "kind": "construct_point",
      "target_var": "C",
      "expr": {
        "kind": "arith",
        "op": "+",
        "left": { "kind": "var", "name": "B" },
        "right": { "kind": "vector_from_points", "from_point": "A", "to_point": "D" }
