    {
      "kind": "construct_point",
      "target_var": "B_prime",
      "expr": {
        "kind": "arith",
        "op": "+",
        "left": { "kind": "var", "name": "B" },
        "right": { "kind": "vector_from_points", "from_point": "A", "to_point": "A_prime" }
      },
      "model_assumption": "BB' song song và bằng AA'",
      "source_fact_id": "hinh_lap_phuong"
    },
    {
      "kind": "construct_point",
      "target_var": "D_prime",
      "expr": {
        "kind": "arith",
        "op": "+",
        "left": { "kind": "var", "name": "D" },
        "right": { "kind": "vector_from_points", "from_point": "A", "to_point": "A_prime" }
      },
      "model_assumption": "DD' song song và bằng AA'",
      "source_fact_id": "hinh_lap_phuong"
    },
    {
      "kind": "construct_point",
      "target_var": "C_prime",
      "expr": {
        "kind": "arith",
        "op": "+",
        "left": { "kind": "var", "name": "C" },
        "right": { "kind": "vector_from_points", "from_point": "A", "to_point": "A_prime" }
      },
      "model_assumption": "CC' song song và bằng AA'",
      "source_fact_id": "hinh_lap_phuong"
    },
    {
      "kind": "construct_point",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "C",
        "b": "C_prime"
      },
      "source_fact_id": "m_trung_diem_cc_phay"
    },
    {
      "kind": "construct_point",
      "target_var": "I",
      "expr": {
        "kind": "midpoint",
        "a": "A",
        "b": "C_prime"
      },
      "source_fact_id": "i_trung_diem_ac_phay"
    },
    {
      "kind": "construct_line",
      "target_var": "BM",
      "through_a": "B",
      "through_b": "M"
    },
    {
      "kind": "assign",
      "target_var": "khoang_cach_i_bm",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "I",
        "wrt": "BM"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách tính khoảng cách từ một điểm đến một đường thẳng trong không gian bằng cách sử dụng tọa độ và các phép dựng hình cơ bản."
}

